package com.pp.shaderlod.optimization;

import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** Current integrated digest API; generated byte data is a unit fixture, not a pack certificate. */
class SourceArchiveDigestTest {
    @TempDir Path directory;
    private static final SourceArchiveDigest.DigestFactory SHA=()->MessageDigest.getInstance("SHA-256");
    private static String expected(byte[] bytes) throws Exception {
        return HexFormat.of().formatHex(SHA.create().digest(bytes));
    }
    @Test void completeBytesAtChunkBoundariesAndSameStatMutation() throws Exception {
        Path path=directory.resolve("bytes.bin");
        for(int size:new int[]{0,1,65535,65536,65537,131071,131072,131073,2097155}) {
            byte[] bytes=new byte[size];new Random(9182).nextBytes(bytes);Files.write(path,bytes);
            for(boolean streaming:new boolean[]{false,true})
                assertEquals(expected(bytes),SourceArchiveDigest.sha256(path,streaming,SHA));
        }
        var stamp=Files.getLastModifiedTime(path);long size=Files.size(path);
        String original=SourceArchiveDigest.sha256(path,true,SHA);
        byte[] bytes=Files.readAllBytes(path);bytes[bytes.length/2]^=1;
        Files.write(path,bytes);Files.setLastModifiedTime(path,stamp);
        assertEquals(size,Files.size(path));assertEquals(stamp,Files.getLastModifiedTime(path));
        assertNotEquals(original,SourceArchiveDigest.sha256(path,true,SHA));
        assertEquals(expected(bytes),SourceArchiveDigest.sha256(path,true,SHA));
    }
    @Test void missingProviderReadFailureAndErrorPriorityRemainStrict() throws Exception {
        for(boolean streaming:new boolean[]{false,true}) {
            assertThrows(NoSuchFileException.class,()->SourceArchiveDigest.sha256(directory.resolve("absent"),streaming,SHA));
            assertThrows(IOException.class,()->SourceArchiveDigest.sha256(directory,streaming,SHA));
            SourceArchiveDigest.DigestFactory absent=()->{throw new NoSuchAlgorithmException("provider-unavailable");};
            var provider=assertThrows(NoSuchAlgorithmException.class,()->SourceArchiveDigest.sha256(new ByteArrayInputStream(new byte[10]),streaming,absent));
            assertEquals("provider-unavailable",provider.getMessage());
            var input=new InputStream(){int count;public int read()throws IOException{
                if(count++>=70001)throw new IOException("read-provider-failure");return 17;
            }};
            var read=assertThrows(IOException.class,()->SourceArchiveDigest.sha256(input,streaming,absent));
            assertEquals("read-provider-failure",read.getMessage());
        }
    }
    @Test void actualZipFilesystemAndZeroProgressStreamExhaustAllBytes() throws Exception {
        try(var fs=FileSystems.newFileSystem(java.net.URI.create("jar:"+directory.resolve("provider.zip").toUri()),Map.of("create","true"))) {
            Path entry=fs.getPath("/bounded.bin");byte[] bytes=new byte[65537];new Random(31).nextBytes(bytes);Files.write(entry,bytes);
            for(boolean streaming:new boolean[]{false,true})assertEquals(expected(bytes),SourceArchiveDigest.sha256(entry,streaming,SHA));
        }
        byte[] bytes={4,5,6};var input=new ByteArrayInputStream(bytes){boolean first=true;
            @Override public synchronized int read(byte[] buffer,int offset,int length){if(first){first=false;return 0;}return super.read(buffer,offset,length);}
        };
        assertEquals(expected(bytes),SourceArchiveDigest.sha256(input,true,SHA));
    }
}
